# ---- writer with per-record asserts ----
EXPECTED = ["LR3-002","LR3-004","LR3-006","LR3-008","LR3-010","LR3-101","LR3-104","LR3-107",
            "LR3-110","LR3-112","LR3-114","LR3-116","LY-001","LY-002","LY-003","LY-004",
            "LY-005","LY-006","LY-007","LY-008"]
assert sorted(DATA.keys()) == sorted(EXPECTED), "case set mismatch"

written = 0
trig = {"changed_main": 0, "reserve_used": 0, "disputed": 0}
for cid in EXPECTED:
    rec = DATA[cid]
    assert set(rec.keys()) == {"case_id","prediction_text","basis","confidence","trigger"}, cid
    assert rec["case_id"] == cid
    assert isinstance(rec["confidence"], float) and 0.0 <= rec["confidence"] <= 1.0, cid
    t = rec["trigger"]
    assert set(t.keys()) == {"changed_main","reserve_used","disputed","reason"}, cid
    if cid.startswith("LY"):
        for k in trig:
            if t[k]:
                trig[k] += 1
    else:
        assert t == {"changed_main": False, "reserve_used": False, "disputed": False, "reason": ""}, cid
    path = os.path.join(OUT, cid + ".json")
    with open(path, "w", encoding="utf-8") as f:
        json.dump(rec, f, ensure_ascii=False, indent=1)
    with open(path, encoding="utf-8") as f:
        back = json.load(f)
    assert back == rec, cid
    written += 1

print("written:", written)
print("liuyao trigger counts:", trig)
